package database

import (
	"encoding/csv"
	"log"
	"sort"
	"strconv"
	"strings"

	"github.com/isfir/wowsims-turtle/sim/core/proto"
)

// Generated by tools/database/loot/extract_loot_sources.py from the Turtle world database.
//
// LootSources.csv: item_id,npc_id,object_id,name,zone_id,chance
// LootZones.csv:   zone_id,name

const worldDropName = "World Drop"

// ApplyLootSources adds drop sources (ordered by drop chance, highest first) to the items in db,
// along with the NPCs and zones they reference.
func ApplyLootSources(db *WowDatabase, lootSourcesCSV, lootZonesCSV string) {
	for _, row := range readCSVRows(lootZonesCSV) {
		id := parseInt32(row[0])
		if id == 0 {
			continue
		}
		db.MergeZone(&proto.UIZone{Id: id, Name: row[1], Expansion: proto.Expansion_ExpansionVanilla})
	}

	sourcesByItem := make(map[int32][]*proto.DropSource)
	for _, row := range readCSVRows(lootSourcesCSV) {
		if len(row) < 6 {
			continue
		}
		itemID, npcID, objectID, name, zoneID := parseInt32(row[0]), parseInt32(row[1]), parseInt32(row[2]), row[3], parseInt32(row[4])
		chance, err := strconv.ParseFloat(row[5], 64)
		if err != nil {
			log.Fatalf("LootSources.csv: bad chance %q for item %d", row[5], itemID)
		}

		if _, ok := db.Items[itemID]; !ok {
			continue
		}

		src := &proto.DropSource{NpcId: npcID, ObjectId: objectID, ZoneId: zoneID, DropChance: chance}
		if npcID != 0 {
			db.MergeNpc(&proto.UINPC{Id: npcID, Name: name, ZoneId: zoneID})
		} else {
			src.OtherName = name
		}
		sourcesByItem[itemID] = append(sourcesByItem[itemID], src)
	}

	for itemID, drops := range sourcesByItem {
		// World drops have no chance and go last.
		sort.SliceStable(drops, func(i, j int) bool {
			iWorld, jWorld := drops[i].OtherName == worldDropName, drops[j].OtherName == worldDropName
			if iWorld != jWorld {
				return jWorld
			}
			return drops[i].DropChance > drops[j].DropChance
		})

		item := db.Items[itemID]
		// Keep non-drop sources (crafted, quest, ...) from overrides; replace any existing drops.
		var sources []*proto.UIItemSource
		for _, s := range item.Sources {
			if s.GetDrop() == nil {
				sources = append(sources, s)
			}
		}
		for _, d := range drops {
			sources = append(sources, &proto.UIItemSource{Source: &proto.UIItemSource_Drop{Drop: d}})
		}
		item.Sources = sources
	}
}

func readCSVRows(data string) [][]string {
	r := csv.NewReader(strings.NewReader(data))
	rows, err := r.ReadAll()
	if err != nil {
		log.Fatalf("failed to parse CSV: %v", err)
	}
	if len(rows) == 0 {
		return nil
	}
	return rows[1:] // skip header
}

func parseInt32(s string) int32 {
	v, err := strconv.ParseInt(strings.TrimSpace(s), 10, 32)
	if err != nil {
		log.Fatalf("failed to parse int %q: %v", s, err)
	}
	return int32(v)
}
